import referralRoutes from './routes/referrals/index.js'

// Voucher routes
import voucherRoutes from './routes/vouchers/index.js'
import adminVoucherRoutes from './routes/admin/vouchers/index.js'

// Share routes (public, no auth)
import shareRoutes from './routes/share/index.js'

// Storage routes (for local storage mode)
import storageRoutes from './routes/storage/index.js'

// Cron routes
import cronRoutes from './routes/cron/index.js'

const app = express()
const PORT = parseInt(process.env.PORT ?? '4000')

// Trust proxy (Cloudflare Tunnel / Nginx forwards X-Forwarded-Proto)
app.set('trust proxy', 1)

// Security headers
app.use((_req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff')
  res.setHeader('X-Frame-Options', 'DENY')
  res.setHeader('X-XSS-Protection', '0') // rely on CSP instead
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin')
  // CSP handled by Nginx on frontend, not needed on API responses
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains')
  res.removeHeader('X-Powered-By')
  next()
})

// Middleware — fail-fast neu prod thieu CORS_ORIGIN (tranh rang nham open CORS)
if (process.env.NODE_ENV === 'production' && !process.env.CORS_ORIGIN) {
  throw new Error('CORS_ORIGIN phai duoc set trong production')
}
app.use(cors({
  origin: (process.env.CORS_ORIGIN ?? 'http://localhost:3000')
    .split(',')
    .map(s => s.trim()),
  credentials: true,
}))
app.use(cookieParser())
app.use(requestLogger)
app.use(authMiddleware)

// Storage routes — MUST be before express.json() because upload-chunk
// sends binary body (application/octet-stream). express.json() consumes
// the body stream even for non-JSON content types, leaving req.body empty

// for the route-level express.raw() parser.
app.use('/api/storage', storageRoutes)

// JSON body parser — after binary upload routes
app.use(express.json({ limit: '10mb' }))

// Health check
app.get('/api/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() })
})


// Public auth routes — IP rate-limit chong brute-force (budget du cho SPA phien lam viec binh thuong
// va test suite; attacker brute force 300+/phut se bi chan. Can xem xet them captcha + progressive delay.)
app.use('/api/auth/register', ipRateLimit('auth:register', 30, 60))
app.use('/api/auth/login', ipRateLimit('auth:login', 300, 60))
app.use('/api/auth/refresh', ipRateLimit('auth:refresh', 300, 60))
app.use('/api/auth', registerRoute)
app.use('/api/auth', loginRoute)
app.use('/api/auth', logoutRoute)
app.use('/api/auth', refreshRoute)

// User routes
app.use('/api/users', userMeRoute)

// Album routes
app.use('/api/albums', albumRoutes)

// Image routes
app.use('/api/images', imageRoutes)

// Payment routes
app.use('/api/payments', paymentRoutes)

// Public data routes (plans & payment methods for upgrade page)
app.use('/api/plans', publicPlanRoutes)
app.use('/api/payment-methods', publicPaymentMethodRoutes)

// Admin routes (protected by adminGuard)
app.use('/api/admin/dashboard', adminGuard, adminDashboardRoutes)
app.use('/api/admin/users', adminGuard, adminUserRoutes)
app.use('/api/admin/albums', adminGuard, adminAlbumRoutes)
app.use('/api/admin/payments', adminGuard, adminPaymentRoutes)
app.use('/api/admin/plans', adminGuard, adminPlanRoutes)
app.use('/api/admin/payment-methods', adminGuard, adminPaymentMethodRoutes)
app.use('/api/admin/settings', adminGuard, adminSettingsRoutes)
app.use('/api/admin/logs', adminGuard, adminLogRoutes)
app.use('/api/admin/vouchers', adminGuard, adminVoucherRoutes)

// Voucher routes (user-facing, requires auth)

app.use('/api/vouchers', voucherRoutes)

// Referral routes
app.use('/api/referrals', referralRoutes)

// Share routes (public album sharing, no auth) — IP rate-limit chong abuse guest like/comment
app.use('/api/share', ipRateLimit('share', 60, 60), shareRoutes)

// Cron routes
app.use('/api/cron', cronRoutes)

// Error handler — structured logging + debug mode toggle
app.use(async (err: Error & { statusCode?: number; code?: string }, req: express.Request, res: express.Response, _next: express.NextFunction) => {
  const status = err.statusCode ?? 500

  // Build comprehensive error context
  const meta: Record<string, unknown> = {
    requestId: req.requestId,
    method: req.method,
    url: req.originalUrl,
    userId: req.user?.sub,
    statusCode: status,
    errorName: err.constructor?.name !== 'Error' ? err.constructor?.name : undefined,
    errorCode: err.code,
  }

  // Always include stack for 5xx, include for 4xx too (helps trace origin)
  if (status >= 500) {
    meta.stack = err.stack
    // Include request context for debugging 5xx
    if (req.body && !Buffer.isBuffer(req.body)) {
      try {
        // Redact sensitive keys truoc khi log (password, token, secret, authorization)
        const redacted = JSON.parse(JSON.stringify(req.body))
        const SENSITIVE = ['password', 'passwordHash', 'token', 'accessToken', 'refreshToken', 'secret', 'authorization', 'apiKey']
        const redact = (obj: unknown): void => {
          if (!obj || typeof obj !== 'object') return
          for (const k of Object.keys(obj as Record<string, unknown>)) {
            if (SENSITIVE.some(s => k.toLowerCase().includes(s.toLowerCase()))) {
              (obj as Record<string, unknown>)[k] = '[REDACTED]'
            } else {
              redact((obj as Record<string, unknown>)[k])
            }
          }
        }
        redact(redacted)
        meta.reqBody = JSON.stringify(redacted).slice(0, 1000)
      } catch { /* skip */ }
    }
    if (req.query && Object.keys(req.query).length > 0) {

      meta.query = req.query
    }
    meta.ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress
    meta.ua = (req.headers['user-agent'] ?? '').slice(0, 150)
    // Include cause chain if present
    const cause = (err as Error & { cause?: Error }).cause
    if (cause) {
      meta.cause = { message: cause.message, name: cause.constructor?.name, stack: cause.stack?.split('\n').slice(0, 3).join('\n') }
    }
  } else {
    // 4xx — lighter context but still include stack origin (first 3 lines)
    meta.stackOrigin = err.stack?.split('\n').slice(0, 4).join('\n')
  }

  const logLevel = status >= 500 ? 'error' : 'warn' as const
  logger[logLevel](err.message, meta)

  // Check debug mode for detailed 5xx responses
  if (status >= 500) {
    const debugMode = await getSetting('debug_mode', 'false')
    if (debugMode === 'true') {
      return res.status(status).json({
        message: err.message,
        errorName: err.constructor?.name,
        errorCode: err.code,
        stack: err.stack,
        requestId: req.requestId,
        context: { method: req.method, url: req.originalUrl, query: req.query },
      })
    }
    return res.status(status).json({
      message: 'Lỗi hệ thống, vui lòng thử lại sau',
      requestId: req.requestId,
    })
  }

  // 4xx — always return original message + requestId
  res.status(status).json({
    message: err.message,
    requestId: req.requestId,
  })
})

// Fallback error handler (catches anything missed above)
app.use(globalErrorHandler)

async function start() {
  await connectRedis()
  await initStorage()
  await initSocketEmitter()

  // Validate Google Drive config (non-fatal — Drive is optional)
  const driveStatus = validateDriveConfig()
  logger[driveStatus.ok ? 'info' : 'warn'](driveStatus.message)

  // Serve local storage public files — dynamic middleware that works
  // even when admin switches storage_backend to 'local' at runtime.
  // Registered once; on each request checks the current provider's publicDir.
  const { default: path } = await import('path')
  let _cachedDir: string | null = null
  let _cachedStatic: express.RequestHandler | null = null

  app.use('/storage/public', (req, res, next) => {
    const pubDir = getLocalPublicDir()
    if (!pubDir) return next()

    // Re-create express.static only when the directory changes
    if (pubDir !== _cachedDir) {
      _cachedDir = pubDir
      _cachedStatic = express.static(pubDir, { maxAge: '30d', immutable: true })
      logger.info(`Serving local storage public files from ${pubDir}`)
    }
    _cachedStatic!(req, res, next)
  })

  // Start API server
  app.listen(PORT, async () => {
    logger.info(`API server running on port ${PORT}`)

    // Send restart notification email to admin
    try {
      const adminEmail = await getSetting('admin_email')
      if (adminEmail) {
        const storageBackend = await getSetting('storage_backend', 'r2')
        await mailService.send({
          to: adminEmail,
          template: 'system_restart',
          data: {
            timestamp: new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }),
            nodeVersion: process.version,
            port: String(PORT),
            storageBackend,
          },
        })
        logger.info('Restart notification email sent to admin')
      }

    } catch (err) {
      logger.warn('Failed to send restart notification email', { error: (err as Error).message })
    }
  })

  // Start Socket.io server on separate port
  try {
    const SOCKET_PORT = parseInt(process.env.SOCKET_PORT ?? '4001')
    const { createServer } = await import('http')
    const { setupSocketServer } = await import('./plugins/socket.js')
    const socketHttpServer = createServer()
    await setupSocketServer(socketHttpServer)
    socketHttpServer.listen(SOCKET_PORT, () => {
      logger.info(`Socket.io server running on port ${SOCKET_PORT}`)
    })
    socketHttpServer.on('error', (err: NodeJS.ErrnoException) => {
      if (err.code === 'EADDRINUSE') {
        logger.warn(`Socket.io port ${SOCKET_PORT} in use, skipping. API still running.`)
      } else {
        logger.error('Socket.io error', { stack: (err as Error).stack })
      }
    })
  } catch (err) {
    logger.warn('Socket.io server failed to start, API continues', { stack: (err as Error).stack })
  }
}

// Catch unhandled errors globally
process.on('unhandledRejection', (reason) => {
  const err = reason instanceof Error ? reason : new Error(String(reason))
  logger.fatal(`Unhandled rejection: ${err.message}`, {
    errorName: err.constructor?.name,
    stack: err.stack,
  })
})

process.on('uncaughtException', (err) => {
  // ECONNRESET la loi binh thuong khi client disconnect, khong can crash
  if ((err as NodeJS.ErrnoException).code === 'ECONNRESET') {
    logger.warn(`Connection reset: ${err.message}`)
    return
  }
  logger.fatal(`Uncaught exception: ${err.message}`, {
    errorName: err.constructor?.name,
    stack: err.stack,
  })
  // Give logger time to flush, then exit
  setTimeout(() => process.exit(1), 1000)
})

export function adminGuard(req: Request, _res: Response, next: NextFunction) {
  if (!req.user || req.user.role !== 'admin') {
    const err = new Error('Admin only') as Error & { statusCode: number }
    err.statusCode = 403
    throw err
  }
  next()
}

