const SKIP_VISIT_PATHS = ['/api/cron', '/api/health']

export async function authMiddleware(req: Request, _res: Response, next: NextFunction) {
  const token = req.cookies?.access_token
    ?? req.headers.authorization?.replace('Bearer ', '')

  if (token) {
    const payload = await jwtUtils.verify(token)
    if (payload) {
      req.user = payload
      const isSkip = SKIP_VISIT_PATHS.some(p => req.path.startsWith(p))
      if (!isSkip) {
        incrVisit(payload.sub).catch(() => {})
      }
    }
  }
  next()
}

export function requireAuth(req: Request): JWTPayload {
  if (!req.user) {
    const err = new Error('Chưa đăng nhập') as Error & { statusCode: number }
    err.statusCode = 401
    throw err
  }
  return req.user
}

export function requireAdmin(req: Request): JWTPayload {
  const user = requireAuth(req)
  if (user.role !== 'admin') {
    const err = new Error('Không có quyền') as Error & { statusCode: number }
    err.statusCode = 403
    throw err
  }
  return user
}

export function requirePlan(req: Request, plan: 'basic' | 'pro'): JWTPayload {
  const user = requireAuth(req)
  const order: Record<string, number> = { free: 0, basic: 1, pro: 2, admin: 99 }
  if ((order[user.planCode] ?? 0) < order[plan]) {
    const err = new Error(`Yêu cầu gói ${plan} trở lên`) as Error & { statusCode: number }
    err.statusCode = 403
    throw err
  }
  return user
}

import { Request, Response, NextFunction } from 'express'
import { redis } from '../utils/redis.js'

// Rate-limit theo IP cho cac endpoint public (login, register, share, voucher...)
// Khac voi rateLimit.ts — khong yeu cau req.user
const IS_PROD = process.env.NODE_ENV === 'production'
const LOCAL_IPS = new Set(['127.0.0.1', '::1', '::ffff:127.0.0.1'])

export function ipRateLimit(prefix: string, maxRequests: number, windowSec = 60) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      // Cloudflare / Nginx forward client IP
      const ip = (req.headers['cf-connecting-ip'] as string)
        || (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim()
        || req.socket.remoteAddress
        || 'unknown'

      // Bypass localhost trong dev/test — tranh E2E suite false positive 429.
      // Prod van bi chan vi dung cf-connecting-ip (real client IP).
      if (!IS_PROD && LOCAL_IPS.has(ip)) return next()

      const key = `ipRate:${prefix}:${ip}`
      const current = await redis.incr(key)
      if (current === 1) {
        await redis.expire(key, windowSec)
      }

      if (current > maxRequests) {
        res.setHeader('Retry-After', String(windowSec))
        return res.status(429).json({
          message: 'Quá nhiều yêu cầu, vui lòng thử lại sau',
        })
      }
    } catch {
      // Redis down — allow through (fail-open)
    }
    next()
  }
}

export function rateLimit(prefix: string, maxRequests: number, windowSec = 60) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) return next()

    try {
      const key = `rate:${prefix}:${req.user.sub}`
      const current = await redis.incr(key)
      if (current === 1) {
        await redis.expire(key, windowSec)
      }

      if (current > maxRequests) {
        return res.status(429).json({ message: 'Quá nhiều yêu cầu, vui lòng thử lại sau' })
      }
    } catch {
      // If Redis fails, allow the request through
    }
    next()
  }
}

import { Request, Response, NextFunction } from 'express'
import { ulid } from 'ulid'
import { logger } from '../utils/logger.js'

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      requestId?: string
    }
  }
}

// Capture response body for error logging

function captureResponseBody(res: Response): { getBody: () => string | null } {
  const chunks: Buffer[] = []
  const originalWrite = res.write.bind(res)
  const originalEnd = res.end.bind(res)

  res.write = function (chunk: any, ...args: any[]) {
    if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
    return (originalWrite as any)(chunk, ...args)
  } as any

  res.end = function (chunk: any, ...args: any[]) {
    if (chunk) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
    return (originalEnd as any)(chunk, ...args)
  } as any

  return {
    getBody: () => {
      if (chunks.length === 0) return null
      try {
        return Buffer.concat(chunks).toString('utf-8').slice(0, 500)
      } catch {
        return null
      }
    },
  }
}

export function requestLogger(req: Request, res: Response, next: NextFunction) {
  const requestId = ulid()
  req.requestId = requestId
  res.setHeader('X-Request-Id', requestId)

  const start = Date.now()

  // Capture response body only for non-2xx (to log error messages)
  const capture = captureResponseBody(res)

  // Log request body for mutation methods
  const hasMutationBody = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method) && req.body
  let reqBodyPreview: string | undefined
  if (hasMutationBody) {
    try {
      // Skip binary data
      if (Buffer.isBuffer(req.body)) {
        reqBodyPreview = `[binary ${req.body.length}B]`
      } else {
        reqBodyPreview = JSON.stringify(req.body).slice(0, 500)
      }
    } catch {
      reqBodyPreview = '[unserializable]'
    }
  }

  res.on('finish', () => {
    const durationMs = Date.now() - start
    const status = res.statusCode
    const meta: Record<string, unknown> = {
      requestId,
      method: req.method,
      url: req.originalUrl,
      userId: req.user?.sub,
      statusCode: status,
      durationMs,
    }

    // Add request body for non-2xx or slow requests
    if (reqBodyPreview && (status >= 400 || durationMs > 3000)) {
      meta.reqBody = reqBodyPreview
    }

    // Add response body for errors
    if (status >= 400) {
      const resBody = capture.getBody()
      if (resBody) {
        meta.resBody = resBody
      }
    }

    // Add IP and user-agent for important requests
    if (status >= 400 || req.originalUrl.includes('/auth/')) {
      meta.ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress
      meta.ua = (req.headers['user-agent'] ?? '').slice(0, 150)
    }

    if (status >= 500) {
      logger.error(`${req.method} ${req.originalUrl} ${status} (${durationMs}ms)`, meta)
    } else if (status >= 400) {
      logger.warn(`${req.method} ${req.originalUrl} ${status} (${durationMs}ms)`, meta)
    } else {
      logger.info(`${req.method} ${req.originalUrl} ${status} (${durationMs}ms)`, meta)
    }
  })

  next()
}

