// POST /:token/images/:imageId/comments — guest comment (no auth required)
router.post('/:token/images/:imageId/comments', async (req, res) => {
  const { token, imageId } = req.params
  const { guestName, content } = req.body

  const result = await validateShareToken(token)
  if (result.error) return res.status(result.error.status).json({ message: result.error.message })
  const share = result.share!

  // Check allowComment permission
  if (!share.allowComment) {
    return res.status(403).json({ message: 'Chức năng bình luận đã bị tắt cho link chia sẻ này' })
  }

  // Validate guestName
  if (!guestName || typeof guestName !== 'string' || guestName.trim().length === 0) {
    return res.status(400).json({ message: 'Tên người bình luận không được để trống' })
  }
  if (guestName.trim().length > 50) {
    return res.status(400).json({ message: 'Tên người bình luận không được vượt quá 50 ký tự' })
  }

  // Validate content
  if (!content || typeof content !== 'string' || content.trim().length === 0) {
    return res.status(400).json({ message: 'Nội dung bình luận không được để trống' })
  }

  const safeContent = sanitizeText(content, 2000)
  if (!safeContent) return res.status(400).json({ message: 'Nội dung bình luận không hợp lệ' })

  const safeGuestName = sanitizeText(guestName, 50)
  if (!safeGuestName) return res.status(400).json({ message: 'Tên người bình luận không hợp lệ' })

  // Validate image belongs to shared album
  const imgResult = await validateSharedImage(imageId, share.albumId)
  if (imgResult.error) return res.status(imgResult.error.status).json({ message: imgResult.error.message })

  const commentId = ulid()
  await db.insert(comments).values({
    id: commentId,
    imageId,
    userId: null,
    guestName: safeGuestName,
    content: safeContent,
    createdAt: new Date(),
  })

  // Update comment count
  await db.update(images).set({ commentCount: sql`comment_count + 1` }).where(eq(images.id, imageId))

  res.json({
    id: commentId,
    content: safeContent,
    createdAt: new Date(),
    userId: null,
    guestName: safeGuestName,
    displayName: safeGuestName,
    avatarKey: null,
  })
})

// GET /:token/images/:imageId/download-url — guest download (no auth, no plan check)
router.get('/:token/images/:imageId/download-url', async (req, res) => {
  const { token, imageId } = req.params

  const result = await validateShareToken(token)
  if (result.error) return res.status(result.error.status).json({ message: result.error.message })
  const share = result.share!

  // Check allowDownload permission
  if (!share.allowDownload) {
    return res.status(403).json({ message: 'Chức năng tải xuống đã bị tắt cho link chia sẻ này' })
  }

  // Validate image belongs to shared album and is ready
  const [image] = await db.select().from(images)

    .where(and(eq(images.id, imageId), eq(images.albumId, share.albumId), eq(images.status, 'ready')))
    .limit(1)

  if (!image) return res.status(404).json({ message: 'Ảnh không tồn tại hoặc chưa sẵn sàng' })

  // Return proxy download URL
  res.json({ url: `/api/share/${token}/images/${imageId}/download` })
})

// GET /:token/images/:imageId/download — proxy download for shared album
router.get('/:token/images/:imageId/download', async (req, res) => {
  const { token, imageId } = req.params

  const result = await validateShareToken(token)
  if (result.error) return res.status(result.error.status).json({ message: result.error.message })
  const share = result.share!

  if (!share.allowDownload) {
    return res.status(403).json({ message: 'Chức năng tải xuống đã bị tắt' })
  }

  const [image] = await db.select().from(images)
    .where(and(eq(images.id, imageId), eq(images.albumId, share.albumId), eq(images.status, 'ready')))
    .limit(1)
  if (!image) return res.status(404).json({ message: 'Ảnh không tồn tại' })

  const stream = await storageFor(image.storageBackend).getStream(image.originalKey)
  const safeName = encodeURIComponent(image.originalName || 'image')
  res.set('Content-Disposition', `attachment; filename="${safeName}"; filename*=UTF-8''${safeName}`)
  res.set('Content-Type', image.mimeType || 'application/octet-stream')
  if (image.originalSize) res.set('Content-Length', image.originalSize.toString())
  stream.pipe(res)
})

export default router

import { Router } from 'express'
import express from 'express'
import { requireAuth } from '../../middleware/auth.js'
import { storage, getStorageBackend } from '../../utils/storage/index.js'
import { jwtVerify } from 'jose'
import { logger } from '../../utils/logger.js'

const router = Router()

// POST /upload-chunk — receive a chunk for multipart upload (both R2 and local)
router.post('/upload-chunk', express.raw({ limit: '6mb', type: '*/*' }), async (req, res) => {
  const user = requireAuth(req)
  const { key, uploadId, partNumber } = req.query
  if (!key || !uploadId || !partNumber) {
    return res.status(400).json({ message: 'Thieu key, uploadId hoac partNumber' })
  }

  const bodySize = Buffer.isBuffer(req.body) ? req.body.length : 0
  if (bodySize === 0) {
    logger.error(`[Chunk] Empty body for part ${partNumber}`, { key, partNumber: Number(partNumber), userId: user.sub, bodyType: typeof req.body, isBuffer: Buffer.isBuffer(req.body) })
    return res.status(400).json({ message: 'Empty chunk body' })
  }
  logger.info(`[Chunk] Uploading part ${partNumber} (${(bodySize / 1024 / 1024).toFixed(1)}MB)`, { key, partNumber: Number(partNumber), bytes: bodySize, userId: user.sub })

  const stor = storage()
  const etag = await stor.uploadPart(key as string, uploadId as string, Number(partNumber), req.body as Buffer)
  logger.debug(`[Chunk] Part ${partNumber} uploaded, ETag=${etag}`, { key, partNumber: Number(partNumber) })
  res.json({ ETag: etag, PartNumber: Number(partNumber) })
})

// PUT /upload-public — receive a public file (avatar, QR) for local storage
router.put('/upload-public', express.raw({ limit: '5mb', type: '*/*' }), async (req, res) => {
  requireAuth(req)
  const backend = await getStorageBackend()
  if (backend !== 'local') return res.status(400).json({ message: 'Chi dung cho local storage' })

  const { key, contentType } = req.query
  if (!key || !contentType) {
    return res.status(400).json({ message: 'Thieu key hoac contentType' })
  }

  await storage().uploadBuffer(key as string, req.body as Buffer, contentType as string)
  res.json({ ok: true })
})

// GET /download — serve private file with JWT token (yeu cau purpose=download va verify key ownership)
router.get('/download', async (req, res) => {
  const { token } = req.query
  if (!token) return res.status(400).json({ message: 'Thieu token' })

  try {
    const secret = new TextEncoder().encode(process.env.JWT_SECRET!)
    const { payload } = await jwtVerify(token as string, secret)
    const { key, filename, purpose } = payload as { key?: string; filename?: string; purpose?: string }

    // Chi chap nhan token duoc cap voi purpose=download — chan reuse access_token
    if (purpose !== 'download') {
      return res.status(403).json({ message: 'Token sai muc dich' })
    }

    if (!key || typeof key !== 'string' || !filename) {
      return res.status(403).json({ message: 'Token thieu truong bat buoc' })
    }

    // Ngan path traversal tren key
    if (key.includes('..') || key.startsWith('/')) {
      return res.status(403).json({ message: 'Key khong hop le' })
    }

    const stream = await storage().getStream(key)
    res.set('Content-Disposition', `attachment; filename="${encodeURIComponent(filename)}"`)
    stream.pipe(res)
  } catch {
    res.status(403).json({ message: 'Token khong hop le hoac het han' })
  }
})

