export function createImageExpiryWorker() {
  return new Worker('image-expiry', async () => {
    const BATCH = 100
    let totalDeleted = 0

    while (true) {
      const expired = await db.select().from(images)
        .where(and(
          lt(images.expiresAt, new Date()),
          ne(images.status, 'uploading'),
        ))
        .limit(BATCH)

      if (expired.length === 0) break

      // Group keys by storage backend
      const byBackend = new Map<string, { priv: string[]; pub: string[] }>()
      for (const i of expired) {
        const b = i.storageBackend || 'r2'
        if (!byBackend.has(b)) byBackend.set(b, { priv: [], pub: [] })
        const g = byBackend.get(b)!
        if (i.originalKey) g.priv.push(i.originalKey)
        if (i.thumbKey) g.pub.push(i.thumbKey)
        if (i.previewKey) g.pub.push(i.previewKey)
      }

      await Promise.all(
        [...byBackend.entries()].flatMap(([backend, { priv, pub }]) => [
          priv.length ? storageFor(backend).deletePrivate(priv) : Promise.resolve(),
          pub.length ? storageFor(backend).deletePublic(pub) : Promise.resolve(),
        ]),
      )

      const ids = expired.map(i => i.id)
      await db.delete(images).where(inArray(images.id, ids))

      const byUser = new Map<string, bigint>()
      for (const img of expired) {
        byUser.set(img.userId, (byUser.get(img.userId) ?? BigInt(0)) + img.originalSize)
      }
      await Promise.all(
        [...byUser.entries()].map(([uid, bytes]) => quotaUtils.subtractUsed(uid, bytes))
      )

      totalDeleted += expired.length
    }

    return { deleted: totalDeleted }
  }, { connection: { url: process.env.REDIS_URL } })
}

async function decodeToTiff(inputStream: NodeJS.ReadableStream): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const dcraw = spawn('dcraw', ['-c', '-w', '-T', '-'], { stdio: ['pipe', 'pipe', 'pipe'] })
    const chunks: Buffer[] = []

    inputStream.pipe(dcraw.stdin)
    dcraw.stdout.on('data', (chunk: Buffer) => chunks.push(chunk))
    dcraw.stdout.on('end', () => resolve(Buffer.concat(chunks)))
    dcraw.on('error', reject)
    dcraw.stderr.on('data', (d: Buffer) => logger.error('[dcraw] ' + d.toString(), { source: 'worker:image-process' }))
    dcraw.on('exit', (code) => { if (code !== 0) reject(new Error(`dcraw exit ${code}`)) })
  })
}

export function createImageWorker() {
  return new Worker('image-process', async (job) => {
    const { imageId, userId, originalKey, mimeType } = job.data
    logger.info(`[Worker] Processing image ${imageId}`, { source: 'worker:image-process', userId, imageId, mimeType, originalKey })
    try {
      // Look up per-image storage backend
      const [imgRow] = await db.select({ storageBackend: images.storageBackend }).from(images).where(eq(images.id, imageId)).limit(1)
      const backend = imgRow?.storageBackend || 'r2'
      const stor = storageFor(backend)

      const rawStream = await stor.getStream(originalKey)

      let sharpInput: Buffer

      if (RAW_MIME_TYPES.has(mimeType)) {
        sharpInput = await decodeToTiff(rawStream)
      } else {
        // Collect stream into buffer for Sharp
        const chunks: Buffer[] = []
        for await (const chunk of rawStream) {
          chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk))
        }
        sharpInput = Buffer.concat(chunks)
      }

      const pipeline = sharp(sharpInput, { failOn: 'none' })

      const [thumbBuf, previewBuf, meta] = await Promise.all([
        pipeline.clone().resize(400).webp({ quality: 80 }).toBuffer(),
        pipeline.clone().resize(1920, 1920, { fit: 'inside' }).webp({ quality: 85 }).toBuffer(),
        pipeline.metadata(),
      ])

      const base = `${userId}/${imageId}`
      await Promise.all([
        stor.uploadBuffer(`${base}/thumb.webp`, thumbBuf, 'image/webp'),
        stor.uploadBuffer(`${base}/preview.webp`, previewBuf, 'image/webp'),
      ])

      await db.update(images).set({
        thumbKey: `${base}/thumb.webp`, previewKey: `${base}/preview.webp`,
        width: meta.width, height: meta.height, status: 'ready',
      }).where(eq(images.id, imageId))

      logger.info(`[Worker] Image ready ${imageId} (${meta.width}x${meta.height})`, { source: 'worker:image-process', userId, imageId })

      // Auto-set album cover if album has no cover yet (include coverStorageBackend)
      const [img] = await db.select({ albumId: images.albumId, originalName: images.originalName }).from(images).where(eq(images.id, imageId)).limit(1)
      if (img?.albumId) {
        await db.update(albums).set({ coverKey: `${base}/thumb.webp`, coverStorageBackend: backend })

          .where(and(eq(albums.id, img.albumId), isNull(albums.coverKey)))
      }

      const imageName = img?.originalName ?? imageId

      await emitToUser(userId, {
        type: 'image:ready', imageId,
        thumbUrl: stor.publicUrl(`${base}/thumb.webp`),
        message: `Ảnh ${imageName} đã xử lý xong`,
      })
    } catch (err) {
      const e = err as Error & { code?: string }
      logger.error(`[Worker] Image failed ${imageId}: ${e.message}`, { source: 'worker:image-process', userId, imageId, errorName: e.constructor?.name, errorCode: e.code, originalKey: job.data.originalKey, mimeType: job.data.mimeType, stack: e.stack })
      await db.update(images).set({ status: 'failed' }).where(eq(images.id, imageId))

      // Query image name for meaningful notification
      const [failedImg] = await db.select({ originalName: images.originalName }).from(images).where(eq(images.id, imageId)).limit(1)
      const failedName = failedImg?.originalName ?? imageId

      await emitToUser(userId, { type: 'image:failed', imageId, reason: String(err), message: `Xử lý ảnh ${failedName} thất bại` })
      throw err
    }
  }, { connection: { url: process.env.REDIS_URL }, concurrency: 3 })
}

async function start() {
  logger.info('[Worker] Connecting to Redis...', { source: 'worker' })
  await connectRedis()
  await initSocketEmitter()

  logger.info('[Worker] Starting workers...', { source: 'worker' })
  const imageWorker = createImageWorker()
  const expiryWorker = createImageExpiryWorker()
  const storageWorker = createStorageMonitorWorker()
  const emailWorker = createEmailWorker()
  const driveImportWorker = createDriveImportWorker()

  await setupRecurringJobs()

  logger.info('[Worker] All workers started: image-process(3), image-expiry, storage-monitor, email-send(5), drive-import(2)', { source: 'worker' })

  // Graceful shutdown
  const shutdown = async () => {
    logger.info('[Worker] Shutting down...', { source: 'worker' })
    await Promise.all([
      imageWorker.close(),
      expiryWorker.close(),
      storageWorker.close(),
      emailWorker.close(),
      driveImportWorker.close(),
    ])
    process.exit(0)
  }

  process.on('SIGTERM', shutdown)
  process.on('SIGINT', shutdown)
}

start().catch((err) => {
  logger.fatal('[Worker] Fatal error', { source: 'worker', stack: (err as Error).stack })
  process.exit(1)
})

export function createStorageMonitorWorker() {
  return new Worker('storage-monitor', async () => {
    const today = new Date().toISOString().slice(0, 10)

    const [[imgStats], [userCount], [albumCount], [todayRev], [todayUsers]] = await Promise.all([
      db.select({
        totalPrivate: sql<string>`COALESCE(SUM(original_size),0)`,
        count: sql<number>`COUNT(*)`,
      }).from(schema.images).where(eq(schema.images.status, 'ready')),
      db.select({ c: sql<number>`COUNT(*)` }).from(schema.users),
      db.select({ c: sql<number>`COUNT(*)` }).from(schema.albums),
      db.select({ t: sql<number>`COALESCE(SUM(amount_vnd),0)` }).from(schema.payments)
        .where(and(eq(schema.payments.status, 'paid'), gte(schema.payments.paidAt!, new Date(today)))),
      db.select({ c: sql<number>`COUNT(*)` }).from(schema.users)
        .where(gte(schema.users.createdAt, new Date(today))),
    ])

    const visitCount = parseInt((await redis.get(`visit:day:${today}`)) ?? '0')

    await db.insert(schema.storageSnapshots).values({
      id: ulid(),
      totalBytesPrivate: BigInt(imgStats.totalPrivate),
      totalBytesPublic: BigInt(imgStats.totalPrivate) / BigInt(10),
      totalUsers: userCount.c, totalImages: imgStats.count,
      totalAlbums: albumCount.c, newUsersToday: todayUsers.c,
      revenueToday: todayRev.t, visitCount,
    })

    // Storage alert threshold
    const [threshRow] = await db.select({ value: schema.systemSettings.value })
      .from(schema.systemSettings)
      .where(eq(schema.systemSettings.key, 'storage_alert_threshold_percent'))
    const threshold = parseInt(threshRow?.value ?? '80')
    const r2LimitBytes = BigInt(parseInt(process.env.R2_LIMIT_GB ?? '10') * 1024 ** 3)
    const usedPct = Number(BigInt(imgStats.totalPrivate) * BigInt(100) / r2LimitBytes)
    if (usedPct >= threshold) {
      await emitToAdmin({ type: 'admin:storage:alert', message: `R2 dùng ${usedPct}%`, usedPercent: usedPct })
    }

    // Error spike check
    const [spikeRow] = await db.select({ value: schema.systemSettings.value })
      .from(schema.systemSettings)
      .where(eq(schema.systemSettings.key, 'image_error_spike_threshold'))
    const spikeN = parseInt(spikeRow?.value ?? '20')
    const [errRow] = await db.select({ c: sql<number>`COUNT(*)` }).from(schema.images)
      .where(and(eq(schema.images.status, 'failed'),
        gte(schema.images.createdAt, new Date(Date.now() - 3600_000))))
    if (errRow.c >= spikeN) {
      await emitToAdmin({ type: 'admin:image:error:spike', count: errRow.c, threshold: spikeN })
    }

export function useApi<T = unknown>() {
  const data = ref<T | null>(null)
  const loading = ref(false)
  const error = ref<string | null>(null)

  const execute = async (fn: () => Promise<T>): Promise<T | null> => {
    loading.value = true
    error.value = null
    try {
      const result = await fn()
      data.value = result
      return result
    } catch (e: any) {
      error.value =
        e?.response?.data?.message ??
        e?.message ??
        'Đã có lỗi xảy ra, vui lòng thử lại'
      return null
    } finally {
      loading.value = false
    }
  }

  const reset = () => {
    data.value = null
    loading.value = false
    error.value = null
  }

  return { data, loading, error, execute, reset }
}

export function useApiList<T = unknown>() {
  const items = ref<T[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)
  const total = ref(0)
  const hasMore = ref(false)
  const cursor = ref<string | null>(null)

  const fetch = async (fn: () => Promise<{ items: T[]; total?: number; nextCursor?: string | null }>) => {
    loading.value = true
    error.value = null
    try {
      const result = await fn()
      items.value = result.items ?? []
      total.value = result.total ?? items.value.length
      cursor.value = result.nextCursor ?? null
      hasMore.value = !!result.nextCursor
    } catch (e: any) {
      error.value = e?.response?.data?.message ?? 'Không thể tải dữ liệu'
      items.value = []
    } finally {
      loading.value = false
    }
  }

  const fetchMore = async (fn: () => Promise<{ items: T[]; nextCursor?: string | null }>) => {
    if (!hasMore.value || loading.value) return
    loading.value = true
    try {
      const result = await fn()
      items.value = [...items.value, ...(result.items ?? [])] as T[]
      cursor.value = result.nextCursor ?? null
      hasMore.value = !!result.nextCursor
    } catch (e: any) {
      error.value = e?.response?.data?.message ?? 'Không thể tải thêm'
    } finally {
      loading.value = false
    }
  }

  const reset = () => {
    items.value = []
    total.value = 0
    cursor.value = null
    hasMore.value = false
    error.value = null
  }

  return { items, loading, error, total, hasMore, cursor, fetch, fetchMore, reset }
}

export function useNotify() {
  const auth = useAuthStore()
  const notifStore = useNotificationStore()
  const uploadStore = useUploadStore()
  const adminStore = useAdminStore()

  function setupListeners() {
    const socket = getSocket()
    if (!socket) return

    // Remove previous listener to prevent leak on reconnect
    socket.off('notification')

    socket.on('notification', (payload: Record<string, unknown>) => {
      // Server emits flat objects: { type, imageId, message, ... }
      // Extract nested data or use flat payload as data
      const eventType = payload.type as UserEventType | AdminEventType
      const eventData = (payload.data as Record<string, unknown>) ?? payload
      const imageId = (eventData.imageId ?? payload.imageId) as string | undefined

      notifStore.add({
        id: crypto.randomUUID(),
        type: eventType,
        message: (payload.message as string) || '',
        data: eventData,
        read: false,
        createdAt: new Date().toISOString(),
      })

      if (eventType === 'image:ready' && imageId) {
        const file = uploadStore.files.find((f) => f.imageId === imageId)
        if (file) uploadStore.setStatus(file.id, 'ready')
      }

      if (eventType === 'image:failed' && imageId) {
        const file = uploadStore.files.find((f) => f.imageId === imageId)
        if (file) uploadStore.setStatus(file.id, 'failed')
      }

      if ((eventType as string).startsWith('admin:')) {
        adminStore.addAlert({
          id: crypto.randomUUID(),
          level: eventType === 'admin:storage:alert' || eventType === 'admin:image:error:spike' ? 'error' : 'warning',
          message: String(payload.message || ''),
          type: eventType as AdminEventType,
        })
      }
    })
  }

  watch(
    () => auth.isAuthenticated,
    (val) => {
      if (val && auth.accessToken) {
        connectSocket(auth.accessToken)
        setupListeners()
      } else {
        disconnectSocket()
      }
    },
    { immediate: true },
  )
}

