export const useAdminStore = defineStore('admin', () => {
  const alerts = ref<AdminAlert[]>([])

  function addAlert(alert: AdminAlert) {
    if (alerts.value.some((a) => a.id === alert.id)) return
    alerts.value.unshift(alert)
  }

  function dismiss(id: string) {
    const a = alerts.value.find((a) => a.id === id)
    if (a) a.dismissedAt = new Date().toISOString()
  }

  function clear() {
    alerts.value = []
  }

  return { alerts, addAlert, dismiss, clear }
})

import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import api from '@/utils/api'
import type { UserProfile } from '@/types'

// Access token KHONG duoc luu localStorage — chong XSS steal token.
// Chi giu trong memory; refresh token HttpOnly cookie se cap lai khi reload.
const STORAGE_KEY_USER = 'auth_user'

// One-shot cleanup: xoa token cu neu phien truoc da luu
try { localStorage.removeItem('auth_token') } catch { /* ignore */ }

function loadFromStorage<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : null
  } catch { return null }
}

function saveToStorage(key: string, value: unknown) {
  try {
    if (value == null) localStorage.removeItem(key)
    else localStorage.setItem(key, JSON.stringify(value))
  } catch { /* quota exceeded or private mode */ }
}

export const useAuthStore = defineStore('auth', () => {
  // User profile persist cho UX (avoid flicker); access token KHONG persist.
  const user = ref<UserProfile | null>(loadFromStorage<UserProfile>(STORAGE_KEY_USER))
  const accessToken = ref<string | null>(null)
  const loading = ref(false)

  const isAuthenticated = computed(() => !!user.value)
  const isAdmin = computed(() => user.value?.role === 'admin')
  const planCode = computed(() => user.value?.planCode ?? 'free')
  const canDownload = computed(() => ['basic', 'pro'].includes(planCode.value) || isAdmin.value)
  const canFilter = computed(() => ['basic', 'pro'].includes(planCode.value) || isAdmin.value)
  const canEditPhoto = computed(() => planCode.value === 'pro' || isAdmin.value)

  watch(user, (v) => saveToStorage(STORAGE_KEY_USER, v), { deep: true })

  // Cross-tab sync: chi dong bo user profile, khong dong bo token
  if (typeof window !== 'undefined') {
    window.addEventListener('storage', (e) => {
      if (e.key === STORAGE_KEY_USER) {
        user.value = e.newValue ? JSON.parse(e.newValue) : null
        if (!user.value) accessToken.value = null
      }
    })
  }

  async function register(data: { email: string; password: string; displayName: string }) {
    loading.value = true
    try {
      const res = await api.post('/auth/register', data)
      accessToken.value = res.data.accessToken
      user.value = res.data.user
    } finally {
      loading.value = false
    }
  }

  async function login(data: { email: string; password: string }) {
    loading.value = true
    try {
      const res = await api.post('/auth/login', data)
      accessToken.value = res.data.accessToken
      user.value = res.data.user
    } finally {

      loading.value = false
    }
  }

  async function refresh() {
    const res = await api.post('/auth/refresh')
    accessToken.value = res.data.accessToken
    user.value = res.data.user
  }

  async function fetchMe() {
    try {
      const res = await api.get('/users/me')
      user.value = res.data
    } catch {
      user.value = null
      accessToken.value = null
    }
  }

  async function updateProfile(data: Partial<{ displayName: string; bio: string; avatar: File }>) {
    const res = await api.patch('/users/me', data)
    if (user.value) {
      Object.assign(user.value, res.data)
    }
  }

  async function changePassword(data: { currentPassword: string; newPassword: string }) {
    await api.patch('/users/me', data)
  }

  function logout() {
    api.post('/auth/logout').catch(() => {})
    user.value = null
    accessToken.value = null
  }

  return {
    user, accessToken, loading,
    isAuthenticated, isAdmin, planCode,
    canDownload, canFilter, canEditPhoto,
    register, login, refresh, fetchMe,
    updateProfile, changePassword, logout,
  }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { Notification } from '@/types'

export const useNotificationStore = defineStore('notification', () => {
  const items = ref<Notification[]>([])
  const unreadCount = computed(() => items.value.filter((n) => !n.read).length)

  function add(notification: Notification) {
    items.value.unshift(notification)
    if (items.value.length > 50) {
      items.value = items.value.slice(0, 50)
    }
  }

  function markRead(id: string) {
    items.value = items.value.map((n) => n.id === id ? { ...n, read: true } : n)
  }

  function markAllRead() {
    items.value = items.value.map((n) => ({ ...n, read: true }))
  }

  function clear() {
    items.value = []
  }

  return { items, unreadCount, add, markRead, markAllRead, clear }
})

import { defineStore } from 'pinia'
import { ref } from 'vue'

export type ToastType = 'success' | 'error' | 'warning' | 'info'

export interface Toast {
  id: string
  message: string
  type: ToastType
  duration: number
}

export const useToastStore = defineStore('toast', () => {
  const toasts = ref<Toast[]>([])

  function add(message: string, type: ToastType = 'info', duration = 3000) {
    const id = crypto.randomUUID()
    toasts.value.push({ id, message, type, duration })

    if (duration > 0) {
      setTimeout(() => remove(id), duration)
    }
  }

  function remove(id: string) {
    toasts.value = toasts.value.filter(t => t.id !== id)
  }

  return { toasts, add, remove }
})

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { UploadFile, UploadFileStatus } from '@/types'

const MAX_VISIBLE = 5

export const useUploadStore = defineStore('upload', () => {
  const files = ref<UploadFile[]>([])
  const batchTotal = ref(0) // total files selected in current batch

  const summary = computed(() => {
    const total = files.value.length
    const uploading = files.value.filter(f => f.status === 'uploading').length
    const processing = files.value.filter(f => f.status === 'processing').length
    const ready = files.value.filter(f => f.status === 'ready').length
    const failed = files.value.filter(f => f.status === 'failed').length
    const done = ready + failed
    const active = uploading + processing
    const selected = batchTotal.value // total files user selected
    return { total, uploading, processing, ready, failed, done, active, selected }
  })

  // Hard limit: max 5 items. Priority: most recent active first, then recent done
  const visibleFiles = computed(() => {
    const active = files.value.filter(f => f.status === 'uploading' || f.status === 'processing')
    const done = files.value.filter(f => f.status === 'ready' || f.status === 'failed')

    // Take most recent active (up to MAX_VISIBLE)
    const shownActive = active.slice(-MAX_VISIBLE)
    // Fill remaining with most recent done
    const remaining = Math.max(0, MAX_VISIBLE - shownActive.length)
    const shownDone = remaining > 0 ? done.slice(-remaining) : []

    return [...shownActive, ...shownDone]
  })

  // How many files are hidden (not shown in visibleFiles)
  const hiddenCount = computed(() => Math.max(0, files.value.length - visibleFiles.value.length))

  function add(file: UploadFile) {
    files.value.push(file)
  }

  function setProgress(id: string, progress: number, speed?: number) {
    const f = files.value.find((f) => f.id === id)
    if (f) {
      f.progress = Math.min(100, Math.round(progress))
      if (speed !== undefined) f.speed = speed
    }
  }

  function setStatus(id: string, status: UploadFileStatus, imageId?: string) {
    const f = files.value.find((f) => f.id === id)
    if (f) {
      f.status = status
      if (imageId) f.imageId = imageId
    }
  }

  function remove(id: string) {
    files.value = files.value.filter((f) => f.id !== id)
  }

  function clear() {
    files.value = files.value.filter((f) => f.status === 'uploading' || f.status === 'processing')
  }

  function clearAll() {
    files.value = []
    batchTotal.value = 0
  }

  function setBatchTotal(n: number) {
    batchTotal.value = n
  }

  return { files, visibleFiles, hiddenCount, summary, batchTotal, add, setProgress, setStatus, remove, clear, clearAll, setBatchTotal }
})

