function processQueue(error: unknown) {
  failedQueue.forEach((p) => {
    if (error) p.reject(error)
    else p.resolve(undefined)
  })
  failedQueue = []
}

// ── Request interceptor: auth + logging ──
api.interceptors.request.use((config) => {
  const auth = useAuthStore()
  if (auth.accessToken) {
    config.headers.Authorization = `Bearer ${auth.accessToken}`
  }

  // Log all requests
  const isRaw = config.data instanceof Blob || config.data instanceof ArrayBuffer || config.data instanceof Uint8Array
  const bodyInfo = isRaw
    ? `[binary ${config.data.byteLength ?? config.data.size ?? '?'}B]`
    : config.data
      ? JSON.stringify(config.data).slice(0, 200)
      : ''
  console.log(
    `%c[API] ${config.method?.toUpperCase()} ${config.url}`,
    'color:#2563eb',
    config.params ?? '',
    bodyInfo ? `body: ${bodyInfo}` : '',
  )

  // Attach start time for duration calc
  ;(config as any)._startTime = Date.now()

  return config
})

// ── Response interceptor: logging + 401 refresh ──
api.interceptors.response.use(
  (res) => {
    const dur = Date.now() - ((res.config as any)._startTime ?? Date.now())
    const dataPreview = typeof res.data === 'object'
      ? JSON.stringify(res.data).slice(0, 300)
      : String(res.data).slice(0, 300)
    console.log(
      `%c[API] ${res.status} ${res.config.method?.toUpperCase()} ${res.config.url} (${dur}ms)`,
      'color:#16a34a',
      dataPreview,
    )
    return res
  },
  async (error) => {

    const config = error.config
    const dur = Date.now() - ((config as any)?._startTime ?? Date.now())
    const status = error.response?.status ?? 0
    const errData = error.response?.data ?? error.message

    console.error(
      `%c[API] ${status} ${config?.method?.toUpperCase()} ${config?.url} (${dur}ms)`,
      'color:#dc2626',
      errData,
    )

    const originalRequest = error.config
    const isAuthRequest = originalRequest?.url?.includes('/auth/')
    if (error.response?.status === 401 && !originalRequest._retry && !isAuthRequest) {
      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject })
        }).then(() => api(originalRequest))
      }

      originalRequest._retry = true
      isRefreshing = true

      try {
        const auth = useAuthStore()
        await auth.refresh()
        processQueue(null)
        return api(originalRequest)
      } catch (e) {
        processQueue(e)
        const auth = useAuthStore()
        if (auth.isAuthenticated) {
          auth.logout()
        }
        return Promise.reject(e)
      } finally {
        isRefreshing = false
      }
    }
    return Promise.reject(error)
  },
)

export default api

export function debounce<T extends (...args: unknown[]) => unknown>(fn: T, delay = 300): T {
  let timer: ReturnType<typeof setTimeout>
  return ((...args: unknown[]) => {
    clearTimeout(timer)
    timer = setTimeout(() => fn(...args), delay)
  }) as unknown as T
}

export function formatVnd(amount: number | null | undefined): string {
  if (amount == null || isNaN(amount)) return '0 ₫'
  return new Intl.NumberFormat('vi-VN', {
    style: 'currency',
    currency: 'VND',
  }).format(amount)
}

export function formatBytes(bytes: string | number): string {
  const b = typeof bytes === 'string' ? Number(bytes) : bytes
  if (!b || isNaN(b) || b <= 0) return '0 B'
  const k = 1024
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(b) / Math.log(k))
  return `${parseFloat((b / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`
}

export function formatGB(bytes: string | number): string {
  const b = typeof bytes === 'string' ? Number(bytes) : bytes
  return `${(b / (1024 ** 3)).toFixed(2)} GB`
}

export function formatDate(dateStr: string | null | undefined): string {
  if (!dateStr) return '—'
  const d = new Date(dateStr)
  if (isNaN(d.getTime())) return '—'
  return d.toLocaleDateString('vi-VN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  })
}

export function formatDateTime(dateStr: string | null | undefined): string {
  if (!dateStr) return '—'
  const d = new Date(dateStr)
  if (isNaN(d.getTime())) return '—'
  return d.toLocaleString('vi-VN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export function timeAgo(dateStr: string): string {
  const now = Date.now()
  const diff = now - new Date(dateStr).getTime()
  const minutes = Math.floor(diff / 60000)
  if (minutes < 1) return 'vừa xong'
  if (minutes < 60) return `${minutes} phút trước`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} giờ trước`
  const days = Math.floor(hours / 24)
  if (days < 30) return `${days} ngày trước`
  return formatDate(dateStr)
}

export function cdnUrl(key: string | null): string {
  if (!key) return '/placeholder-avatar.svg'
  if (key.startsWith('http')) return key
  return `${import.meta.env.VITE_CDN_URL || ''}/${key}`
}

export function storagePercent(used: string | number, limit: string | number): number {
  const u = typeof used === 'string' ? Number(used) : used
  const l = typeof limit === 'string' ? Number(limit) : limit
  if (l === 0) return 0
  return Math.round((u / l) * 100)
}

